using Xunit;

public sealed class BlogQueriesTests : IAsyncLifetime
{
    private SqliteConnection _connection = null!;
    private BlogContext _database = null!;

    public async Task InitializeAsync()
    {
        _connection = new SqliteConnection("Data Source=:memory:");
        await _connection.OpenAsync();

        var options = new DbContextOptionsBuilder<BlogContext>()
            .UseSqlite(_connection)
            .Options;

        _database = new BlogContext(options);
        await _database.Database.EnsureCreatedAsync();
    }

    public async Task DisposeAsync()
    {
        await _database.DisposeAsync();
        await _connection.DisposeAsync();
    }

    [Fact]
    public async Task GivenNoPosts_WhenGettingTotalPostViews_ThenReturnsZero()
    {
        var totalViews = await BlogQueries.TotalPostViews(
            _database,
            CancellationToken.None);

        Assert.Equal(0, totalViews);
    }

    [Fact]
    public async Task GivenPosts_WhenGettingTotalPostViews_ThenReturnsSumOfViews()
    {
        GivenPosts(12, 8, 5);

        await _database.SaveChangesAsync();

        var totalViews = await BlogQueries.TotalPostViews(
            _database,
            CancellationToken.None);

        Assert.Equal(25, totalViews);
    }

    private void GivenPosts(params int[] views)
    {
        var blog = new Blog
        {
            Name = "Test blog"
        };

        foreach (var (viewCount, index) in Enumerate(views))
        {
            blog.Posts.Add(new Post
            {
                Title = $"Post {index + 1}",
                Views = viewCount
            });
        }

        _database.Blogs.Add(blog);
    }

    private static IEnumerable<(int ViewCount, int Index)> Enumerate(int[] views)
    {
        for (var index = 0; index < views.Length; index++)
        {
            yield return (views[index], index);
        }
    }
}
